def normalize_class_key(class_str):
    """Maps class titles, aliases, or raw strings to canonical dictionary keys."""
    if not class_str or not isinstance(class_str, str):
        return "pathless"
    c_low = class_str.strip().lower()

    # Exact canonical identity for the Classic 10
    canonical_10 = {
        "fighter": "fighter",
        "wizard": "wizard",
        "rogue": "rogue",
        "cleric": "cleric",
        "ranger": "ranger",
        "paladin": "paladin",
        "druid": "druid",
        "bard": "bard",
        "barbarian": "barbarian",
        "monk": "monk",
        "warlock": "warlock",
    }
    if c_low in canonical_10:
        return canonical_10[c_low]

    # Exact canonical identity for Psionic classes (XPH & DSP)
    psionic_canon = {
        "psion": "psion",
        "psychic_warrior": "psychic_warrior",
        "soulknife": "soulknife",
        "wilder": "wilder",
        "aegis": "aegis",
        "vitalist": "vitalist",
        "tactician": "tactician",
        "cryptic": "cryptic",
        "dread": "dread",
        "marksman": "marksman",
    }
    if c_low in psionic_canon:
        return psionic_canon[c_low]

    # Specific required exact aliases
    alias_map = {
        "warrior": "fighter",
        "vanguard": "fighter",
        "mage": "wizard",
        "aether_slinger": "wizard",
        "thief": "rogue",
        "infiltrator": "rogue",
        "wilderness_ranger": "ranger",
        "magi_saboteur": "engineer",
        "hunter": "ranger",
        "templar": "cleric",
        "priest": "cleric",
        "arcanist": "wizard",
        "slinger": "wizard",
        "assassin": "rogue",
        "berserker": "barbarian",
        "juggernaut": "barbarian",
        "crusader": "paladin",
        "shifter": "druid",
        "virtuoso": "bard",
        "skald": "bard",
        "ascetic": "monk",
        "invocator": "warlock",
        "hellfire": "warlock",
        "eldritch": "warlock",
        "hellfire_warlock": "warlock",
        "eldritch_theurge": "warlock",
        "psychic warrior": "psychic_warrior",
        "mind blade": "soulknife",
        "astral suit": "aegis",
        "collective healer": "vitalist",
    }
    if c_low in alias_map:
        return alias_map[c_low]

    # Legacy non-breaking classes
    if c_low == "engineer" or "artificer" in c_low or "saboteur" in c_low or "engineer" in c_low:
        return "engineer"
    if c_low == "psion" or "phrenic" in c_low or "mentalist" in c_low or "psion" in c_low:
        return "psion"
    if c_low == "pathless":
        return "pathless"

    # Substring matching for descriptive titles like "Fighter (Martial Weaponmaster)"
    if "wilderness" in c_low:
        return "ranger"
    if "psychic_warrior" in c_low or "psychic warrior" in c_low:
        return "psychic_warrior"
    if "soulknife" in c_low or "mind blade" in c_low:
        return "soulknife"
    if "wilder" in c_low:
        return "wilder"
    if "aegis" in c_low or "astral suit" in c_low:
        return "aegis"
    if "vitalist" in c_low or "collective healer" in c_low:
        return "vitalist"
    if "tactician" in c_low:
        return "tactician"
    if "cryptic" in c_low:
        return "cryptic"
    if "dread" in c_low:
        return "dread"
    if "marksman" in c_low:
        return "marksman"
    if "barbarian" in c_low or "berserker" in c_low:
        return "barbarian"
    if "paladin" in c_low or "crusader" in c_low:
        return "paladin"
    if "druid" in c_low or "shifter" in c_low:
        return "druid"
    if "bard" in c_low or "virtuoso" in c_low or "skald" in c_low:
        return "bard"
    if "monk" in c_low or "ascetic" in c_low:
        return "monk"
    if "warlock" in c_low or "eldritch" in c_low or "invocator" in c_low:
        return "warlock"
    if "fighter" in c_low or "warrior" in c_low or "vanguard" in c_low:
        return "fighter"
    if "wizard" in c_low or "mage" in c_low or "aether_slinger" in c_low or "slinger" in c_low or "arcanist" in c_low:
        return "wizard"
    if "rogue" in c_low or "thief" in c_low or "infiltrator" in c_low:
        return "rogue"
    if "cleric" in c_low or "templar" in c_low:
        return "cleric"
    if "ranger" in c_low or "hunter" in c_low:
        return "ranger"

    return "pathless"


def initialize_combat_resource(player):
    """
    Ensures player dictionary has a valid combat_resource sub-dictionary.
    Initializes resource according to player's class doctrine.
    """
    if "combat_resource" not in player or not isinstance(player["combat_resource"], dict) or "name" not in player["combat_resource"]:
        c_key = normalize_class_key(player.get("class", "pathless"))
        c_data = CLASS_FEATS_TREE.get(c_key, CLASS_FEATS_TREE["pathless"])
        r_info = c_data["resource"]
        player["combat_resource"] = {
            "name": r_info["name"],
            "current": r_info["start"],
            "max": r_info["max"],
            "type": r_info["type"]
        }
    return player["combat_resource"]


def update_combat_resource(player, delta):
    """
    Adjusts the player's combat resource by delta (positive or negative).
    Clamps within bounds (0 to max). For psion/strain, handles push-your-luck warning.
    Returns transaction summary dict.
    """
    res = initialize_combat_resource(player)
    old_val = res.get("current", 0)
    max_val = res.get("max", 100)
    r_type = res.get("type", "generic")

    new_val = max(0, min(max_val, old_val + delta))
    res["current"] = new_val

    warning = None
    if r_type == "strain":
        if new_val >= 100:
            warning = "CRITICAL PSYCHIC OVERLOAD! Backlash triggers self-stun and nosebleed trauma!"
        elif new_val >= 75:
            warning = "WARNING: Cognitive strain approaching dangerous threshold (75%+)."
    elif r_type == "heat":
        if new_val >= 100:
            warning = "OVERHEAT DETECTED! Chassis venting required to prevent burn damage!"

    return {
        "name": res["name"],
        "old": old_val,
        "new": new_val,
        "max": max_val,
        "delta": delta,
        "warning": warning
    }


def get_combat_resource_display(player):
    """Returns formatted display info for HUD rendering."""
    res = initialize_combat_resource(player)
    cur = res.get("current", 0)
    m = res.get("max", 100)
    pct = round(cur / m, 2) if m > 0 else 0.0
    r_type = res.get("type", "generic")

    if r_type == "strain":
        display_str = f"{cur}% / {m}% Strain"
    elif r_type in ["power_points", "pp"]:
        display_str = f"{cur} / {m} PP"
    elif r_type in ["customization_points", "cp"]:
        display_str = f"{cur} / {m} CP"
    elif r_type in ["momentum", "focus", "ki"]:
        display_str = f"{cur} / {m} Charges"
    elif r_type == "rage":
        display_str = f"{cur} / {m} Rage"
    elif r_type == "zeal":
        display_str = f"{cur} / {m} Zeal"
    elif r_type == "primal":
        display_str = f"{cur} / {m} Primal"
    elif r_type == "cadence":
        display_str = f"{cur} / {m} Cadence"
    else:
        display_str = f"{cur} / {m}"

    return {
        "name": res.get("name", "Combat Resource"),
        "current": cur,
        "max": m,
        "percentage": pct,
        "type": r_type,
        "display": display_str
    }


