_SLUG_CLEAN_RE = re.compile(r'[^a-zA-Z0-9_\-\s]')
_SLUG_SPACE_RE = re.compile(r'[\s\-]+')

def _sanitize_character_slug(name):
    clean = _SLUG_CLEAN_RE.sub('', str(name)).strip()
    return _SLUG_SPACE_RE.sub('_', clean) or "survivor"

